// Follow the redirect chain hop by hop (no automatic following) from both
// https:// and http://, and flag loops, long chains, downgrades and error pages.
const MAX_HOPS = 10;
const raw = String($input.first().json.body?.domain ?? '').trim();
const hasScheme = /^https?:[/][/]/i.test(raw);
const bare = raw.replace(/^https?:[/][/]/i, '').replace(/[/]$/, '');

// The Code sandbox has no URL class, so resolve Location headers by hand.
const resolve = (location, base) => {
  if (/^https?:[/][/]/i.test(location)) return location;
  const [, origin, path = '/'] = base.match(/^(https?:[/][/][^/?#]+)([^?#]*)/i);
  if (location.startsWith('//')) return base.split(':')[0] + ':' + location;
  if (location.startsWith('/')) return origin + location;
  return origin + path.replace(/[^/]*$/, '') + location;
};

const follow = async (startUrl) => {
  const hops = [];
  const seen = new Set();
  let url = startUrl;
  let problem = null;
  let final = null;
  for (let i = 0; i <= MAX_HOPS; i++) {
    if (seen.has(url)) { problem = 'redirect_loop'; break; }
    if (i === MAX_HOPS) { problem = 'too_many_redirects'; break; }
    seen.add(url);
    let res;
    try {
      res = await this.helpers.httpRequest({ method: 'GET', url, returnFullResponse: true, ignoreHttpStatusErrors: true, disableFollowRedirect: true, timeout: 10000, encoding: 'text' });
    } catch (e) {
      hops.push({ url, status: null, error: e.message });
      problem = 'request_failed';
      break;
    }
    const status = res.statusCode;
    const location = res.headers?.location || null;
    hops.push({ url, status, location });
    if (status >= 300 && status < 400 && location) {
      url = resolve(location, url);
      continue;
    }
    final = { url, status };
    if (status >= 400) problem = 'final_error';
    break;
  }
  const downgrade = hops.some((h, i) => h.url.startsWith('https://') && hops[i + 1]?.url.startsWith('http://'));
  return { start: startUrl, ok: !problem, problem, redirects: Math.max(hops.length - 1, 0), final_url: final?.url ?? null, final_status: final?.status ?? null, https_downgrade: downgrade, hops };
};

const primary = await follow(hasScheme ? raw : 'https://' + bare);
const fromHttp = hasScheme ? null : await follow('http://' + bare);
const httpUpgradesToHttps = fromHttp ? (fromHttp.final_url || '').startsWith('https://') : null;

// problems = the site is broken for visitors; warnings = worth fixing, not an outage.
const problems = [primary.problem, fromHttp?.problem].filter(Boolean);
const warnings = [];
if (primary.https_downgrade || fromHttp?.https_downgrade) warnings.push('https_downgrade');
if (fromHttp && fromHttp.ok && !httpUpgradesToHttps) warnings.push('http_not_redirected_to_https');
if (!primary.ok && fromHttp?.ok) warnings.push('https_broken_but_http_works');

return [{ json: {
  domain: bare,
  ok: problems.length === 0,
  problems: [...new Set(problems)],
  warnings,
  https_chain: primary,
  http_chain: fromHttp,
  http_upgrades_to_https: httpUpgradesToHttps,
} }];
